"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["37554"],{51669(e){e.exports=JSON.parse('{"id":"V4-145","slug":"triple-net-lease","term":"Triple Net Lease","also_known_as":[],"difficulty":"Advanced","definition":"A triple net lease is a commercial lease in which the tenant pays rent plus the property\u2019s three main running costs: property taxes, building insurance and maintenance.","explanation":["Under a triple net lease, often written as NNN lease, the tenant takes on most of the costs and responsibilities of the property. The landlord receives rent with relatively few deductions, making the income more predictable.","Other lease types allocate costs differently. In a gross lease, the landlord pays most property costs out of a higher rent. In single net and double net leases, the tenant pays some, but not all, of the three main costs.","For example, a retail chain might lease a standalone store under a 15-year triple net lease, paying a fixed rent plus all property taxes, insurance and maintenance.","Triple net leases are common in the United States for single-tenant commercial properties, such as shops, restaurants, pharmacies, warehouses and bank branches. Investors value them for their stable, bond-like income. The main risk is the tenant\u2019s financial strength, since the income depends on one tenant continuing to pay. In the United Kingdom, a similar arrangement is called a full repairing and insuring lease."],"note":"","total":1725,"prev":{"slug":"trial-balance","term":"Trial Balance"},"next":{"slug":"trust","term":"Trust"}}')}}]);